        <ArrowUpToLine
          aria-hidden
          className="size-3.5 shrink-0 text-ink-3 opacity-0 transition-opacity group-hover/name:opacity-100 group-focus-visible/name:opacity-100"
        />
      )}
    </button>
  );
}

